import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "<p>PNGからJPGへの変換は、ファイルを小さくすることで有名です。ただし節約量は、すべての画像で同じではありません。スクリーンショットは90%小さくなるかもしれませんが、シンプルなアイコンはむしろ大きくなる場合があります。</p>\n<p>節約を左右する要素を理解すれば、変換前に結果を予測でき、大切なものを守る画質設定を選べます。</p>\n<p>この記事では、画像の種類ごとに数字を正直に見て、トレードオフを平易な言葉で解説します。記事の数字が手元の画像に当てはまるか、<a href=\"/ja/png-jpg-henkan/\">PNGからJPGへの変換ツール</a>で試して確かめてみましょう。</p>\n<h2 id=\"why-png-is-big\">PNGファイルが大きい理由</h2>\n<p>PNGは可逆形式です。つまり、すべての画素を正確に保存します。その正確さがバイトを食い、特に無限の質感と色の変化がある詳細な画像では顕著です。</p>\n<p>写真には、何百万もの微妙に異なる色があります。PNGはそれぞれを記述しなければなりませんが、JPGはそれらをなめらかなグラデーションに単純化できます。目はその違いにほとんど気付きません。</p>\n<p>ノイズは、隠れたコストです。カメラの粒状感、画面の質感、アンチエイリアス処理された輪郭は、すべてランダムに見えるデータです。ランダムなデータは、可逆形式では圧縮しにくいです。</p>\n<p>スクリーンショットは、最悪のケースです。フル画面の撮影は、写真、文字、グラデーション、画面の要素を混ぜ、PNGはそのすべてを完全な品質で保存します。</p>\n<h2 id=\"why-jpg-is-small\">JPGファイルがはるかに小さい理由</h2>\n<p>JPGは非可逆形式です。つまり、容量を節約するために細部を捨てます。近くの画素をブロックにまとめ、ブロック内の色を単純化します。</p>\n<p>なめらかな部分は、非常によく圧縮できます。青い空、白い壁、ぼけた背景は、JPGではごくわずかなバイトしか必要としません。PNGは、それでもすべての画素を記述しなければなりません。</p>\n<p>画質設定は、単純化の積極性を調整します。85%では、単純化は目に見えません。50%では、明らかになります。</p>\n<p>写真やスクリーンショットでは、この交換は優れています。目には、通常の表示サイズで捨てられた細部が見えません。ファイルは10分の1のサイズに縮みます。</p>\n<h2 id=\"savings-by-image-type\">画像の種類別の節約量</h2>\n<p>スクリーンショットが最も節約でき、たいてい80〜90%です。5MBのRetinaスクリーンショットは、85%のJPGで500KBになります。文字も読みやすいままです。</p>\n<p>PNGとして保存された写真は、70〜85%節約できます。12MBのPNG写真は、1.5MBから2MBのJPGになり、メールでの送信やアップロードがはるかに簡単です。</p>\n<p>シンプルなグラフィックは、最も節約が少なく、しばしば30〜50%です。ベタ塗りの色のロゴは、PNGとしてもすでに上手に圧縮できているので、JPGが節約できる余地は少なくなります。</p>\n<p>小さな単色アイコンは、縮むどころか大きくなる場合があります。20KBのアイコンが25KBのJPGになるかもしれません。JPGは、シンプルな画像にはPNGが必要としないヘッダーのオーバーヘッドを追加するからです。</p>\n<h2 id=\"quality-slider-maths\">画質スライダーを実用的な言葉で</h2>\n<p>スライダーは20%から100%まであり、各段階がサイズと画質の両方を変えます。その関係は直線的ではなく、多くの人を驚かせます。</p>\n<p>100%から90%では、目に見える変化がないのに、ファイルはしばしば半分になります。これが、範囲全体で最もよい交換で、90がよい出発点である理由です。</p>\n<p>90%から80%では、ファイルはさらに半分になり、じっくり見てもわずかな柔らかさしか分かりません。これが、ほとんどのスクリーンショットと写真の最適点です。</p>\n<p>80%から60%では、節約が小さくなり、ダメージが大きくなります。文字はぼやけ、輪郭にハローが出て、グラデーションに帯状の段差ができるので、その交換は割に合いません。</p>\n<h2 id=\"text-at-each-quality\">各画質での文字のシャープさ</h2>\n<p>90%では、スクリーンショットの文字はほぼ完璧に見えます。文字はくっきりし、画素レベルの比較だけがPNGとの違いを示します。</p>\n<p>85%では、通常の読み取りサイズでも文字はきれいなままです。拡大すると、文字の輪郭の周りにわずかな柔らかさが見えます。ただし、スクリーンショットを拡大して読む人はいません。</p>\n<p>75%では、小さな文字が傷み始めます。メニューのラベルや細かい文字にハローが出て、スクリーンショットは少し焦点が合っていないように感じます。</p>\n<p>60%では、文字は目に見えて傷みます。文字が背景ににじみ、スクリーンショットはプロらしくなくなります。文字のあるものには、このレベルを避けてください。</p>\n<h2 id=\"photos-at-each-quality\">各画質での写真</h2>\n<p>写真は、スクリーンショットより低い画質によく耐えます。80%のポートレートはきれいに見えます。肌と髪が、圧縮をよく隠すからです。</p>\n<p>風景は、さらに多くを求めます。葉、水、遠くの建物といった細部は、80%を下回ると目に見えて柔らかくなります。ただし全体の画像は、依然として問題なく見えます。</p>\n<p>商品写真は、輪郭の周りに注意が必要です。白い背景に対するシャープな商品の輪郭は、低画質でハローが出る場合があり、ショップページでは安っぽく見えます。</p>\n<p>写真は、80〜85%が実用的な下限です。それ以下では、節約は小さく、ダメージは目に見えるので、その交換はよくありません。</p>\n<h2 id=\"when-savings-disappear\">節約が消えるとき</h2>\n<p>色の少ないシンプルなグラフィックは、あまり節約できません。フラットなアイコンや2色の図は、PNGとしてもすでに上手に圧縮できているので、JPGが単純化できるものは残っていません。</p>\n<p>非常に小さい画像も、あまり節約できません。30KBの画像は、取り除くデータがほとんどなく、JPGのヘッダーが節約分を食べてしまいます。</p>\n<p>ノイズの多い画像は、想定より節約が少なくなります。ノイズはエンコーダーにはランダムに見え、ランダムなデータは両方の形式で圧縮しにくいです。</p>\n<p>変換後のファイルが元のファイルとほとんど変わらない大きさなら、PNGはすでに効率的でした。その画像は、PNGのままにして、変換を飛ばしてください。</p>\n<h2 id=\"choosing-the-right-setting\">作業に合った設定の選び方</h2>\n<p>書類に入れるスクリーンショットは、88〜90%を使ってください。文字はシャープに残り、ファイルは80%小さくなり、書類はプロらしく見えます。</p>\n<p>Webサイトへ送る写真は、80〜85%を使ってください。画像はきれいに見え、ページは速く読み込まれ、節約も大きいです。</p>\n<p>サイズ制限のあるフォームへ送る画像は、85から始め、ファイルが収まるまで5ポイントずつ下げてください。各段階のあとに、文字を確認します。</p>\n<p>印刷へ送る画像は、92〜95%を使ってください。印刷では画面で隠れる欠点が見え、1枚の重要な画像なら余分なサイズも安いものです。</p>\n<h2 id=\"comparing-before-after\">変換前後を正しく比較する</h2>\n<p>ファイルサイズだけで画質を判断してはいけません。小さなファイルは、文字が読めなければ無意味です。大きなファイルは、画像が小さいものと同じに見えるなら無駄です。</p>\n<p>比較ビューアを使って、変換後のJPGと元のPNGを確認してください。重要な部分まで拡大します。文字、顔、シャープな輪郭です。</p>\n<p>画像は、実際の表示サイズで確認してください。300%に拡大したときに見える欠点は、画像が幅600ピクセルで表示されるなら関係ありません。</p>\n<p>2つの画質で変換して、直接比較してください。85%と90%の違いは、しばしば目に見えません。小さいファイルが正しい選択です。</p>\n<h2 id=\"batch-savings\">バッチの節約はすぐ積み重なる</h2>\n<p>1枚のスクリーンショットで4MB節約するのは、ささいに感じます。50枚のスクリーンショットで各4MB節約すれば、200MBです。メールが送れるか、差し戻されるかの違いです。</p>\n<p>Webサイトは、バッチの節約の恩恵を最も受けます。20枚のPNGスクリーンショットがあるページは60MBになるかもしれませんが、JPG版は8MBで、ページは数分ではなく数秒で読み込めます。</p>\n<p>ストレージも恩恵を受けます。PNGから85%のJPGに変換した写真アーカイブは、80%小さくなり、何年もの新しい写真のための容量が空きます。</p>\n<p>各変換のあと、バッチ概要を記録してください。すべてのファイルの節約量が合計され、よいバッチは手間に見合う劇的な数字を示します。</p>\n<h2 id=\"when-not-to-convert\">まったく変換すべきでないとき</h2>\n<p>透過が必要なロゴは変換しないでください。JPGは透過を持てず、マットの塗りつぶしが、色付きの背景のロゴの周りに目に見える四角を作ります。</p>\n<p>何度も編集する予定の画像も変換しないでください。JPGは保存のたびにダメージを加えますが、PNGは繰り返しの編集でも劣化しません。</p>\n<p>小さなアイコンも変換しないでください。節約はわずかで、JPG版は元のPNGより大きくなる場合があります。</p>\n<p>保管用のマスターも変換しないでください。元のPNGをマスターコピーとして残し、納品用のコピーを変換すれば、いつでも完璧な原本に戻れます。</p>\n<h2 id=\"webp-alternative\">知っておく価値のあるWebPという代替案</h2>\n<p>WebPは、PNGの変換でJPGを上回ることが多く、特にスクリーンショットではそうです。文字をよりよく保ち、透過も残し、同じ画質でより小さいファイルを作ります。</p>\n<p>85%のWebPに変換したPNGのスクリーンショットは、たいていJPG版より小さく、さらにシャープです。Webサイトには、WebPがよりよい変換先です。</p>\n<p>弱点は互換性です。一部のフォーム、プリンター、古いソフトはWebPを拒みます。JPGは疑問なくどこでも使えます。</p>\n<p>送り先がWebサイトなら、WebPを選んでください。送り先が分からないか古いなら、JPGを選んでください。Webの場合、<a href=\"/ja/png-to-webp/\">PNGからWebPへの変換ツール</a>が対応します。</p>\n<h2 id=\"email-attachment-limits\">メールの添付制限</h2>\n<p>ほとんどのメールサービスは、添付ファイルを20MBから25MBまでに制限しており、PNGのスクリーンショットはあっという間にその上限を超えます。5MBのスクリーンショット5枚は合計25MBで、メールは差し戻されます。</p>\n<p>85%のJPGに変換すれば、そのスクリーンショットは合計約4MBになります。メールはすぐに送れ、受け取る人は同じ画像を見られます。</p>\n<p>1枚の大きなスクリーンショットだけなら、変換だけでたいてい問題は解決します。5MBのPNGは500KBのJPGになり、どの添付制限も大きく下回ります。</p>\n<p>非常に大きな一式は、変換後にJPGを1つのアーカイブにまとめてください。添付ファイルが1つなら、10個より管理が簡単で、受け取る人はすべてを一度にダウンロードできます。</p>\n<p>送る前に、合計サイズを確認してください。送ったあとではなく、送る前にです。添付ファイルのサイズをざっと見るだけで、メールを送ったと思ったあとに届く、厄介な差し戻しメッセージを防げます。</p>\n<h2 id=\"website-loading-speed\">Webサイトの表示速度</h2>\n<p>Webサイトの速度は、画像サイズに大きく依存します。PNGの写真は、最悪の原因の一つです。10枚のPNG写真があるページは30MBになるかもしれませんが、JPG版は4MBです。</p>\n<p>訪問者は、その違いをすぐに感じます。10秒で読み込めるページは読者を失いますが、2秒で読み込める同じページは読者を保ちます。</p>\n<p>検索エンジンも気付きます。Googleは、ページ速度を順位付けの一部として測定するので、JPG画像の速いページは、PNG写真の遅いページより上位に表示されます。</p>\n<p>WebサイトのPNGは、80〜85%のJPGに変換してください。WebPにすれば、さらに小さいファイルになります。画像は同じに見え、ページは劇的に速く感じます。</p>\n<p>変換前後で、ページ速度を測定してください。PageSpeed Insightsのようなツールが、具体的な数字で改善を示し、その手間に見合うことを証明します。</p>\n<h2 id=\"storage-on-phone\">いっぱいのスマホのストレージ</h2>\n<p>PNGのスクリーンショットだらけのスマホは、写真やアプリが必要とするストレージを無駄にします。残さなければならないスクリーンショットを変換し、残りを削除すれば、本当に容量が空きます。</p>\n<p>スマホの設定で、スクリーンショットがどれだけ容量を使っているか確認してください。忘れていた画像に、数百MBが使われていることが多く、数字はしばしば驚くほどです。</p>\n<p>残すスクリーンショットは、85%のJPGに変換してください。文字は読みやすいままで、ファイルは80%小さくなり、スマホは再び余裕を持てます。</p>\n<p>もう必要のないスクリーンショットは削除してください。ほとんどは、ワンタイムコードやチャットのメッセージのような一時的なものです。すべてを残しても、容量の無駄にしかなりません。</p>\n<p>毎月、スクリーンショットを整理するリマインダーを設定してください。毎月5分の整理が、やがてスマホをいっぱいにする、ゆっくりした蓄積を防ぎます。</p>\n<h2 id=\"upload-limits-forms\">フォームのアップロード制限</h2>\n<p>アップロードフォームは、画像を2MBや5MBまでに制限していることが多く、PNGのスクリーンショットは簡単に超えてしまいます。5MBのPNGは差し戻されますが、500KBのJPG版は問題なくアップロードできます。</p>\n<p>フォームを開く前に、画像を変換してください。締め切り間際の変換は、ミスの原因になります。早めの変換なら、結果を確認する時間が残ります。</p>\n<p>フォームの受け付け形式も、サイズ制限と一緒に確認してください。JPGとPNGを一覧に載せていても、WebPを拒否するフォームもあります。サイズと同じくらい、形式も重要です。</p>\n<p>JPGがそれでも大きすぎる場合は、画質を80%に下げてもう一度試してください。この1段階で、ファイルサイズが半分になることが多く、見た目の変化はわずかです。</p>\n<p>フォームが正確なサイズを求める場合は、変換後にファイルサイズ指定圧縮ツールを使ってください。まず変換し、そのあと正確な制限まで圧縮する順番です。</p>\n<h2 id=\"balancing-quality-batch\">バッチ全体の画質のバランス</h2>\n<p>画像の種類が混ざったバッチは、最も弱いファイルに合う画質設定が必要です。文字入りのスクリーンショットは85%以上が必要ですが、写真は80%で十分です。</p>\n<p>スクリーンショットと写真が混ざったバッチは、85%を選んでください。スクリーンショットは読みやすいままで、写真はきれいに見え、ファイルはPNGよりはるかに小さいままです。</p>\n<p>写真だけのバッチは、80%が実用的な選択です。画像はPNGと同じに見え、ファイルは85%のときより小さいです。</p>\n<p>変換後は、最も強いファイルではなく、最も弱いファイルを確認してください。80%で問題なく見える写真は、小さな文字のあるスクリーンショットも問題ないことを証明しません。</p>\n<p>迷ったら、バッチを種類ごとに分けてください。設定を調整した2つのバッチは、妥協した設定の1つのバッチより優れ、余分な1分にはそれだけの価値があります。</p>\n<p>数字が語る話はシンプルです。スクリーンショットと写真は劇的に小さくなり、シンプルなグラフィックはほとんど小さくならず、85%以上の画質が文字を守ります。</p>\n<p>全体のガイドは<a href=\"/ja/blog/png-jpg-henkan-gaido/\">PNGをJPGに変換する完全ガイド</a>、手順は<a href=\"/ja/blog/png-jpg-henkan-houhou/\">PNGをJPGに変換する方法</a>をご覧ください。画像がすでにJPGで、小さくしたい場合は、<a href=\"/ja/\">画像圧縮ツール</a>が次のステップです。</p>";

export const FAQS: BlogArticleFaq[] = [{"question":"スクリーンショットに最適なサイズと画質のバランスは、どの画質設定ですか？","answer":"85%が、スクリーンショットの実用的な最適点です。文字は読みやすいままで、ファイルは約80%小さくなり、通常サイズでは画像はきれいに見えます。75%に下げても、余分に節約できる容量はわずかですが、小さな文字は目に見えて柔らかくなるので、その交換はよくありません。"},{"question":"小さなアイコンがJPGに変換して大きくなったのはなぜですか？","answer":"JPGは、シンプルな画像にはPNGが必要としないヘッダーのオーバーヘッドを追加し、フラットなアイコンにはJPGが単純化できる細部がほとんどありません。20KBの単色アイコンは、JPGとして数KB大きくなる場合があります。シンプルなグラフィックは、PNGのままにしてください。変換では何も節約できません。"},{"question":"写真では90%と80%の画質に目に見える違いはありますか？","answer":"通常の表示サイズでは、ほとんどありません。90%のファイルは、80%のファイルの2倍の大きさになることがよくありますが、じっくり拡大しない限り、両方は同じに見えます。Web用の写真は、80%がより賢い選択です。印刷には、90%以上を使ってください。"},{"question":"PNGスクリーンショットのフォルダを1つのバッチでどれだけ小さくできますか？","answer":"5MBのスクリーンショットが50枚あるフォルダは、合計約250MBです。85%のJPGにすれば、たいてい25MBから40MBに縮みます。85%の節約で、メールで簡単に送れるフォルダと、送れないフォルダの違いです。バッチ概要に、正確な合計が表示されます。"},{"question":"画質を70%以下に下げる意味はありますか？","answer":"まれにあり、100KBまでのアップロード上限といった、厳しいサイズ制限でやむを得ない場合だけです。70%を下回ると、文字はぼやけ、写真は目に見えて傷みます。その小ささが必要な場合は、まず寸法を小さくすることを検討してください。画質スライダーをつぶすより、画質をよく保てます。"},{"question":"Webサイトには、PNGをJPGとWebPのどちらに変換すべきですか？","answer":"Webサイトには、たいていWebPのほうがよいです。文字をよりよく保ち、透過も残し、同じ画質でJPGより小さいファイルを作ります。JPGが勝つのは、送り先が分からないか古い場合だけです。最近のWebサイトには、WebPが正しい変換先です。"}];
